sources.route:
from rulebook import bottom

def width(lows: list[int], highs: list[int]) -> int:
    top = highs[0]
    for item in highs:
        top = item if item > top else top
    return top + bottom(lows)

sources.rulebook:
def bottom(lows: list[int]) -> int:
    best = lows[0]
    for item in lows:
        best = item if item > best else best
    return best

